mapper.select:
SELECT id, title, description, sort, default_cover_source, created_at, updated_at
FROM blog_album
WHERE id = #{id}

SELECT id, album_id, image_url, caption, sort, created_at, updated_at
FROM (
    SELECT p.*,
           ROW_NUMBER() OVER (PARTITION BY p.album_id ORDER BY p.sort ASC, p.id ASC) AS rn
    FROM blog_album_photo p
    WHERE p.album_id IN

        #{albumId}

) t
WHERE t.rn <= #{limitPerAlbum}
ORDER BY t.album_id ASC, t.sort ASC, t.id ASC

SELECT COUNT(1)
FROM blog_album_photo
WHERE album_id = #{albumId}

mapper.update:
UPDATE blog_album
SET default_cover_source = 1
WHERE id = #{id}

UPDATE blog_album_photo
SET album_id = #{albumId},
    image_url = #{imageUrl},
    caption = #{caption},
    sort = #{sort}
WHERE id = #{id}
